8	static string ResolverRuta(string? configurada)
9	{
10	    if (!string.IsNullOrWhiteSpace(configurada)) return Path.GetFullPath(configurada);
11	    foreach (var inicio in new[] { AppContext.BaseDirectory, Directory.GetCurrentDirectory() })
12	        for (var d = new DirectoryInfo(inicio); d != null; d = d.Parent)
13	            if (Directory.Exists(Path.Combine(d.FullName, "data", "api"))) return Path.Combine(d.FullName, "data");
14	    return Path.GetFullPath("data");
15	}
16	
17	// Recorre los escapes \uXXXX del cuerpo: un sustituto alto sin bajo detrás, o un bajo sin alto delante, es inválido.
18	static bool TieneSustitutoSuelto(string t)
19	{
20	    var altoPendiente = false;
21	    for (var i = 0; i < t.Length; i++)
22	    {
23	        if (t[i] != '\\') { if (altoPendiente) return true; continue; }
24	        if (i + 1 < t.Length && t[i + 1] == 'u' && i + 5 < t.Length
25	            && int.TryParse(t.AsSpan(i + 2, 4), System.Globalization.NumberStyles.AllowHexSpecifier,
26	                System.Globalization.CultureInfo.InvariantCulture, out var cu))
27	        {
28	            var alto = cu is >= 0xD800 and <= 0xDBFF;
29	            var bajo = cu is >= 0xDC00 and <= 0xDFFF;
30	            if (altoPendiente && !bajo) return true;
31	            if (bajo && !altoPendiente) return true;
32	            altoPendiente = alto;
33	            i += 5;
34	        }
35	        else
36	        {
37	            if (altoPendiente) return true;
38	            i++; // otro escape (\n, \\, \"): salta el carácter escapado
39	        }
40	    }
41	    return altoPendiente;
42	}
