74	    var medicion = new MedicionUso();
75	
76	    IResult Error(int c, string msg)
77	    {
78	        codigo = c;
79	        return Results.Json(new { error = msg }, statusCode: c);
80	    }
81	
82	    try
83	    {
84	        const int MaxCuerpo = 64 * 1024;
85	        var limite = req.HttpContext.Features.Get<Microsoft.AspNetCore.Http.Features.IHttpMaxRequestBodySizeFeature>();
86	        if (limite is { IsReadOnly: false }) limite.MaxRequestBodySize = MaxCuerpo;
87	
88	        JsonDocument doc;
89	        try
90	        {
91	            using var ms = new MemoryStream();
92	            var buf = new byte[8192];
93	            int n;
94	            while ((n = await req.Body.ReadAsync(buf, req.HttpContext.RequestAborted)) > 0)
95	            {
96	                if (ms.Length + n > MaxCuerpo) return Error(400, "El cuerpo es demasiado grande.");
97	                ms.Write(buf, 0, n);
98	            }
99	            // Un byte inválido en cualquier campo, usado o no, invalida todo el cuerpo.
100	            if (!System.Text.Unicode.Utf8.IsValid(ms.GetBuffer().AsSpan(0, (int)ms.Length)))
101	                return Error(400, "El cuerpo no es un JSON válido.");
102	            // GetString no falla con un escape \ud800 suelto (lo sustituye en silencio): se rechaza aquí.
103	            if (TieneSustitutoSuelto(Encoding.UTF8.GetString(ms.GetBuffer(), 0, (int)ms.Length)))
104	                return Error(400, "El cuerpo no es un JSON válido.");
105	            ms.Position = 0;
106	            doc = await JsonDocument.ParseAsync(ms);
107	        }
108	        catch (JsonException) { return Error(400, "El cuerpo no es un JSON válido."); }
109	        catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
110	        catch (Exception) { return Error(400, "No se pudo leer el cuerpo de la petición."); }
111	
112	        using (doc)
113	        {
114	            var raiz = doc.RootElement;
115	            if (raiz.ValueKind != JsonValueKind.Object) return Error(400, "El cuerpo debe ser un objeto JSON.");
116	
117	            static string? Texto(JsonElement e, string nombre) =>
118	                e.ValueKind == JsonValueKind.Object && e.TryGetProperty(nombre, out var v) && v.ValueKind == JsonValueKind.String
119	                    ? v.GetString() : null;
120	            try
121	            {
122	                preguntaAud = Texto(raiz, "pregunta");
123	                if (raiz.TryGetProperty("usuario", out var uAud))
124	                {
125	                    rolAud = Texto(uAud, "rol");
126	                    idAud = Texto(uAud, "id");
127	                }
128	            }
129	            catch (Exception e) when (e is InvalidOperationException or FormatException)
130	            {
131	                // Bytes que no son UTF-8 válido dentro de una cadena JSON: ParseAsync no falla, GetString sí.
132	                preguntaAud = rolAud = idAud = null;
133	                return Error(400, "El cuerpo no es un JSON válido.");
134	            }
135	
136	            if (string.IsNullOrWhiteSpace(preguntaAud)) return Error(400, "La pregunta es obligatoria.");
137	            if (preguntaAud.Length > 1000) return Error(400, "La pregunta no puede superar 1.000 caracteres.");
138	
139	            if (!raiz.TryGetProperty("usuario", out var u) || u.ValueKind != JsonValueKind.Object)
140	                return Error(400, "El usuario es obligatorio.");
141	            if (rolAud == null) return Error(400, "El rol es obligatorio.");
142	            if (rolAud != "estudiante" && rolAud != "coordinador")
143	                return Error(400, "El rol debe ser 'estudiante' o 'coordinador'.");
144	            if (string.IsNullOrWhiteSpace(idAud)) return Error(400, "El id del usuario es obligatorio.");
145	
146	            var usuario = Permisos.ResolverUsuario(datos, rolAud, idAud);
147	            if (usuario == null) return Error(403, "Usuario no válido.");
148	            if (Permisos.MencionaTercero(datos, usuario, preguntaAud))
149	                return Error(403, "No tienes permiso para consultar datos de otros estudiantes.");
150	
151	            if (string.IsNullOrWhiteSpace(cfg["LLM_API_KEY"]))
152	                return Error(503, "El servicio del modelo no está disponible: falta configurar LLM_API_KEY.");
153	
154	            var plazo = double.TryParse(cfg["Asistente:PlazoSegundos"], System.Globalization.NumberStyles.Float,
155	                System.Globalization.CultureInfo.InvariantCulture, out var seg) && seg > 0 ? seg : 90;
156	            using var cts = CancellationTokenSource.CreateLinkedTokenSource(req.HttpContext.RequestAborted);
157	            cts.CancelAfter(TimeSpan.FromSeconds(plazo));
158	
159	            AsistenteResultado res;
160	            try { res = await asistente.ResponderAsync(usuario, preguntaAud, cts.Token, medicion); }
161	            catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested) { throw; }
162	            catch (Exception e)
163	            {
164	                log.LogWarning("Falla del asistente o del proveedor ({Tipo}).", e.GetType().Name);
165	                return Error(503, "El proveedor del modelo no está disponible.");
166	            }
167	
168	            if (res.PermisoDenegado) return Error(403, "No tienes permiso para consultar esos datos.");
169	
170	            codigo = 200;
171	            citasAud = res.Citas;
172	            return Results.Json(new
173	            {
174	                respuesta = res.Respuesta,
175	                citas = res.Citas.Select(c => new { documento = c.Documento, seccion = c.Seccion }),
176	                usoDatosEstudiante = res.UsoDatosEstudiante,
177	                tokens = medicion.Total,
178	                costoUsd = medicion.CostoUsd,
179	            });
180	        }
181	    }
182	    catch (OperationCanceledException) when (req.HttpContext.RequestAborted.IsCancellationRequested)
183	    {
184	        codigo = 499;
