3	public record Seccion(string Documento, string Encabezado, string Texto);
4	
5	public class Reglamento
6	{
7	    public IReadOnlyList<Seccion> Secciones { get; }
8	
9	    public Reglamento(string carpeta)
10	    {
11	        var lista = new List<Seccion>();
12	        if (Directory.Exists(carpeta))
13	        {
14	            foreach (var archivo in Directory.GetFiles(carpeta, "*.md").OrderBy(f => f, StringComparer.Ordinal))
15	                lista.AddRange(Dividir(Path.GetFileName(archivo), File.ReadAllText(archivo)));
16	        }
17	        Secciones = lista;
18	    }
19	
20	    static IEnumerable<Seccion> Dividir(string documento, string contenido)
21	    {
22	        string? encabezado = null;
23	        var texto = new List<string>();
24	        foreach (var linea in contenido.Split('\n'))
25	        {
26	            var l = linea.TrimEnd('\r');
27	            if (l.StartsWith("## "))
28	            {
29	                if (encabezado != null) yield return new(documento, encabezado, string.Join("\n", texto).Trim());
30	                encabezado = l[3..].Trim();
31	                texto.Clear();
32	            }
33	            else if (encabezado != null) texto.Add(l);
34	        }
35	        if (encabezado != null) yield return new(documento, encabezado, string.Join("\n", texto).Trim());
36	    }
37	
38	    public Seccion? Buscar(string documento, string encabezado) =>
39	        Secciones.FirstOrDefault(s => s.Documento == documento && s.Encabezado == encabezado);
40	
41	    public bool ExisteCita(string documento, string encabezado) => Buscar(documento, encabezado) != null;
42	}
