29	export type TipoError = 'permisos' | 'entrada' | 'proveedor' | 'red' | 'generico';
30	
31	export class ApiError extends Error {
32	  constructor(
33	    public tipo: TipoError,
34	    message: string,
35	  ) {
36	    super(message);
37	  }
38	}
39	
40	export function errorDeEstado(status: number): ApiError {
41	  switch (status) {
42	    case 400:
43	      return new ApiError('entrada', 'La pregunta no es válida. Escribe entre 1 y 1.000 caracteres.');
44	    case 403:
45	      return new ApiError(
46	        'permisos',
47	        'No tienes permiso para consultar esos datos. Solo puedes ver tu propia información o, si eres coordinador, la de tu programa.',
48	      );
49	    case 503:
50	      return new ApiError('proveedor', 'El asistente no está disponible en este momento. Inténtalo de nuevo más tarde.');
51	    default:
52	      return new ApiError('generico', `Ocurrió un error inesperado (código ${status}).`);
53	  }
54	}
