56	async function pedir<T>(url: string, init?: RequestInit): Promise<T> {
57	  let res: Response;
58	  try {
59	    res = await (init ? fetch(url, init) : fetch(url));
60	  } catch {
61	    throw new ApiError('red', 'No se pudo conectar con el servidor. Revisa tu conexión.');
62	  }
63	  if (!res.ok) throw errorDeEstado(res.status);
64	  try {
65	    return (await res.json()) as T;
66	  } catch {
67	    throw new ApiError('generico', 'La respuesta del servidor no es válida.');
68	  }
69	}
